interface Shape {
    method area()
}

class Circle implements Shape {
    method area() {
        return 3.14 * radius * radius
    }
}

class Rectangle implements Shape {
    method area() {
        return width * height
    }
}

class AreaCalculator {
    method calculate(shape: Shape) {
        return shape.area()
    }
}

